-- ============================================================================
-- Assessment kind (check-in vs program readiness) + seed readiness document
-- Questions, scores, stop rules, and outcomes live in JSONB. Edit in Content.
-- ============================================================================

ALTER TABLE public.assessments
  ADD COLUMN IF NOT EXISTS kind TEXT NOT NULL DEFAULT 'check_in';

ALTER TABLE public.assessments
  DROP CONSTRAINT IF EXISTS assessments_kind_check;

ALTER TABLE public.assessments
  ADD CONSTRAINT assessments_kind_check
  CHECK (kind IN ('check_in', 'readiness'));

CREATE INDEX IF NOT EXISTS idx_assessments_kind_active
  ON public.assessments (kind, is_active, display_order);

ALTER TABLE public.user_progress
  ADD COLUMN IF NOT EXISTS readiness_pathway TEXT,
  ADD COLUMN IF NOT EXISTS readiness_at TIMESTAMPTZ,
  ADD COLUMN IF NOT EXISTS readiness_allow_sessions BOOLEAN NOT NULL DEFAULT true,
  ADD COLUMN IF NOT EXISTS readiness_ack_at TIMESTAMPTZ;

-- Public pre-account reads use the service role in the app. This policy lets
-- authenticated admins keep editing; anon is not required for the app path.

INSERT INTO public.assessments (
  id, slug, title, description, instructions, disclaimer, cover_image,
  scoring_method, kind, display_order, is_active, questions, outcomes
) VALUES (
  'b0000000-0000-4000-8000-000000000001',
  'program-readiness',
  'Are You Ready for Self-Directed QHRT?',
  $d$QHRT is an educational, instructional, self-paced and self-directed wellness program designed to support personal awareness, well-being and quality of life.

This short Program Readiness & Suitability Check will help you consider whether self-directed QHRT feels appropriate for you at this time and identify the best starting point for your participation.

There are no right or wrong answers.
Please respond based on how things feel for you right now.$d$,
  'Your responses may recommend one of the following:',
  $n$QHRT is a self-directed educational wellness program and is not designed for emergency or crisis situations. Responses submitted through this website are not monitored in real time.$n$,
  NULL,
  'mean',
  'readiness',
  0,
  true,
  $json$[
    {"key":"safety_intro","heading":"First, Let's Make Sure This Is a Good Time to Participate Independently","section":"safety","text":"Please answer each question honestly.","type":"info","required":false,"reverse":false,"category":null,"showIf":null,"practiceId":null,"stopIf":null,"options":[]},
    {"key":"s1","heading":null,"section":"safety","text":"Are you currently in immediate danger or unable to keep yourself safe?","type":"choice","required":true,"reverse":false,"category":null,"showIf":null,"practiceId":null,"stopIf":{"values":["yes"],"outcomeKey":"immediate"},"options":[{"value":"yes","label":"Yes","score":null},{"value":"no","label":"No","score":null}]},
    {"key":"s2","heading":null,"section":"safety","text":"Are you currently considering acting on thoughts of suicide, self-harm or seriously harming someone else?","type":"choice","required":true,"reverse":false,"category":null,"showIf":null,"practiceId":null,"stopIf":{"values":["yes"],"outcomeKey":"immediate"},"options":[{"value":"yes","label":"Yes","score":null},{"value":"no","label":"No","score":null}]},
    {"key":"s3","heading":null,"section":"safety","text":"Are you currently experiencing severe confusion, disorientation, loss of contact with your surroundings or difficulty reliably caring for yourself?","type":"choice","required":true,"reverse":false,"category":null,"showIf":null,"practiceId":null,"stopIf":{"values":["yes"],"outcomeKey":"immediate"},"options":[{"value":"yes","label":"Yes","score":null},{"value":"no","label":"No","score":null}]},
    {"key":"s4","heading":null,"section":"safety","text":"Are you currently experiencing an urgent or emergency situation that requires immediate outside assistance?","type":"choice","required":true,"reverse":false,"category":null,"showIf":null,"practiceId":null,"stopIf":{"values":["yes"],"outcomeKey":"immediate"},"options":[{"value":"yes","label":"Yes","score":null},{"value":"no","label":"No","score":null}]},
    {"key":"s5","heading":null,"section":"safety","text":"Are you currently so overwhelmed that reflective or self-directed wellness activities feel unmanageable?","type":"choice","required":true,"reverse":false,"category":null,"showIf":null,"practiceId":null,"stopIf":null,"options":[{"value":"yes","label":"Yes","score":null},{"value":"no","label":"No","score":null},{"value":"unsure","label":"Unsure","score":null}]},
    {"key":"independence_intro","heading":"How Ready Do You Feel to Participate Independently?","section":"independence","text":"Choose the response that best describes you right now.","type":"info","required":false,"reverse":false,"category":null,"showIf":null,"practiceId":null,"stopIf":null,"options":[]},
    {"key":"i1","heading":"Recognizing When I Need a Pause","section":"independence","text":"I can usually recognize when an activity is beginning to feel like too much for me.","type":"choice","required":true,"reverse":false,"category":"independence","showIf":null,"practiceId":null,"stopIf":null,"options":[{"value":"yes","label":"Yes","score":3},{"value":"mostly","label":"Mostly","score":2},{"value":"sometimes","label":"Sometimes","score":1},{"value":"not_yet","label":"Not Yet","score":0}]},
    {"key":"i2","heading":"Ability to Pause","section":"independence","text":"I can stop or pause an activity rather than feeling that I have to push myself to continue.","type":"choice","required":true,"reverse":false,"category":"independence","showIf":null,"practiceId":null,"stopIf":null,"options":[{"value":"yes","label":"Yes","score":3},{"value":"mostly","label":"Mostly","score":2},{"value":"sometimes","label":"Sometimes","score":1},{"value":"not_yet","label":"Not Yet","score":0}]},
    {"key":"i3","heading":"Returning to the Present","section":"independence","text":"I have simple ways of helping myself return my attention to the present moment when I need to.","type":"choice","required":true,"reverse":false,"category":"independence","showIf":null,"practiceId":null,"stopIf":null,"options":[{"value":"yes","label":"Yes","score":3},{"value":"mostly","label":"Mostly","score":2},{"value":"sometimes","label":"Sometimes","score":1},{"value":"not_yet","label":"Not Yet","score":0}]},
    {"key":"i4","heading":"Observing My Responses","section":"independence","text":"I can notice thoughts, feelings and physical sensations without feeling that I must immediately react to them.","type":"choice","required":true,"reverse":false,"category":"independence","showIf":null,"practiceId":null,"stopIf":null,"options":[{"value":"yes","label":"Yes","score":3},{"value":"mostly","label":"Mostly","score":2},{"value":"sometimes","label":"Sometimes","score":1},{"value":"not_yet","label":"Not Yet","score":0}]},
    {"key":"i5","heading":"Independent Participation","section":"independence","text":"I am comfortable following instructions and completing activities independently.","type":"choice","required":true,"reverse":false,"category":"independence","showIf":null,"practiceId":null,"stopIf":null,"options":[{"value":"yes","label":"Yes","score":3},{"value":"mostly","label":"Mostly","score":2},{"value":"sometimes","label":"Sometimes","score":1},{"value":"not_yet","label":"Not Yet","score":0}]},
    {"key":"i6","heading":"Personal Resources","section":"independence","text":"I know who or what I can turn to when I want encouragement, assistance or additional personal support.","type":"choice","required":true,"reverse":false,"category":"independence","showIf":null,"practiceId":null,"stopIf":null,"options":[{"value":"yes","label":"Yes","score":3},{"value":"mostly","label":"Mostly","score":2},{"value":"sometimes","label":"Sometimes","score":1},{"value":"not_yet","label":"Not Yet","score":0}]},
    {"key":"i7","heading":"Additional Outside Support","section":"independence","text":"I am willing to seek additional outside support if something feels beyond what I want to manage independently.","type":"choice","required":true,"reverse":false,"category":"independence","showIf":null,"practiceId":null,"stopIf":null,"options":[{"value":"yes","label":"Yes","score":3},{"value":"mostly","label":"Mostly","score":2},{"value":"sometimes","label":"Sometimes","score":1},{"value":"not_yet","label":"Not Yet","score":0}]},
    {"key":"i8","heading":"Privacy","section":"independence","text":"I have access to a reasonably private and comfortable place where I can participate without unnecessary interruption.","type":"choice","required":true,"reverse":false,"category":"independence","showIf":null,"practiceId":null,"stopIf":null,"options":[{"value":"yes","label":"Yes","score":3},{"value":"mostly","label":"Mostly","score":2},{"value":"sometimes","label":"Sometimes","score":1},{"value":"not_yet","label":"Not Yet","score":0}]},
    {"key":"i9","heading":"Time","section":"independence","text":"I can give myself enough time to complete activities without feeling rushed.","type":"choice","required":true,"reverse":false,"category":"independence","showIf":null,"practiceId":null,"stopIf":null,"options":[{"value":"yes","label":"Yes","score":3},{"value":"mostly","label":"Mostly","score":2},{"value":"sometimes","label":"Sometimes","score":1},{"value":"not_yet","label":"Not Yet","score":0}]},
    {"key":"i10","heading":"Personal Choice","section":"independence","text":"I understand that I can pause, stop or return to the program at any time.","type":"choice","required":true,"reverse":false,"category":"independence","showIf":null,"practiceId":null,"stopIf":null,"options":[{"value":"yes","label":"Yes","score":3},{"value":"mostly","label":"Mostly","score":2},{"value":"sometimes","label":"Sometimes","score":1},{"value":"not_yet","label":"Not Yet","score":0}]},
    {"key":"expect_info","heading":"What to Expect from QHRT","section":"expect","text":"QHRT is a structured educational and self-directed wellness program.\n\nActivities may include:\n- guided self-reflection\n- emotional and archetypal language\n- noticing thoughts, feelings and physical sensations\n- breathing and settling activities\n- structured wellness statements\n- reflection prompts\n- educational activities\n- observing personal responses\n- periods of reflection between sessions\n- opportunities to pause, reset and continue at your own pace.\n\nSome activities may bring strong or uncomfortable thoughts, feelings, memories or physical sensations into your awareness.\nYou remain in control of your participation and may pause or stop at any time.\n\nQHRT is designed to support:\n- personal awareness\n- self-understanding\n- personal growth\n- well-being\n- steadiness\n- confidence\n- quality of life.","type":"info","required":false,"reverse":false,"category":null,"showIf":null,"practiceId":null,"stopIf":null,"options":[]},
    {"key":"suitability_intro","heading":"Does This Type of Wellness Program Feel Suitable for You?","section":"suitability","text":"The following questions will help you consider whether this style of learning and participation feels appropriate for you at this time.\n\nThere are no right or wrong answers.","type":"info","required":false,"reverse":false,"category":null,"showIf":null,"practiceId":null,"stopIf":null,"options":[]},
    {"key":"u1","heading":"Personal Reflection","section":"suitability","text":"I am comfortable taking time to reflect on my experiences, responses, habits and personal patterns.","type":"choice","required":true,"reverse":false,"category":"suitability","showIf":null,"practiceId":null,"stopIf":null,"options":[{"value":"yes","label":"Yes","score":3},{"value":"mostly","label":"Mostly","score":2},{"value":"unsure","label":"Unsure","score":1},{"value":"not_right_now","label":"Not Right Now","score":0}]},
    {"key":"u2","heading":"Present-Moment Awareness","section":"suitability","text":"I am comfortable paying attention to what I notice within myself during an activity, including thoughts, feelings and physical sensations.","type":"choice","required":true,"reverse":false,"category":"suitability","showIf":null,"practiceId":null,"stopIf":null,"options":[{"value":"yes","label":"Yes","score":3},{"value":"mostly","label":"Mostly","score":2},{"value":"unsure","label":"Unsure","score":1},{"value":"not_right_now","label":"Not Right Now","score":0}]},
    {"key":"u3","heading":"Strong or Uncomfortable Responses","section":"suitability","text":"I understand that personal reflection may occasionally bring strong or uncomfortable thoughts, feelings, memories or physical sensations into my awareness.","type":"choice","required":true,"reverse":false,"category":"suitability","showIf":null,"practiceId":null,"stopIf":null,"options":[{"value":"yes","label":"Yes","score":3},{"value":"mostly","label":"Mostly","score":2},{"value":"unsure","label":"Unsure","score":1},{"value":"not_right_now","label":"Not Right Now","score":0}]},
    {"key":"u4","heading":"No Need to Force an Experience","section":"suitability","text":"I am willing to allow each activity to unfold naturally without trying to force myself to remember, feel, understand or experience something specific.","type":"choice","required":true,"reverse":false,"category":"suitability","showIf":null,"practiceId":null,"stopIf":null,"options":[{"value":"yes","label":"Yes","score":3},{"value":"mostly","label":"Mostly","score":2},{"value":"unsure","label":"Unsure","score":1},{"value":"not_right_now","label":"Not Right Now","score":0}]},
    {"key":"u5","heading":"Personal Choice","section":"suitability","text":"I am comfortable deciding for myself when to continue, pause, stop or return to an activity later.","type":"choice","required":true,"reverse":false,"category":"suitability","showIf":null,"practiceId":null,"stopIf":null,"options":[{"value":"yes","label":"Yes","score":3},{"value":"mostly","label":"Mostly","score":2},{"value":"unsure","label":"Unsure","score":1},{"value":"not_right_now","label":"Not Right Now","score":0}]},
    {"key":"u6","heading":"Independent Participation","section":"suitability","text":"I am comfortable following instructions and completing activities independently in a self-paced online program.","type":"choice","required":true,"reverse":false,"category":"suitability","showIf":null,"practiceId":null,"stopIf":null,"options":[{"value":"yes","label":"Yes","score":3},{"value":"mostly","label":"Mostly","score":2},{"value":"unsure","label":"Unsure","score":1},{"value":"not_right_now","label":"Not Right Now","score":0}]},
    {"key":"u7","heading":"Personal Pace","section":"suitability","text":"I am willing to move through the program at a pace that feels manageable and appropriate for me rather than rushing to complete it.","type":"choice","required":true,"reverse":false,"category":"suitability","showIf":null,"practiceId":null,"stopIf":null,"options":[{"value":"yes","label":"Yes","score":3},{"value":"mostly","label":"Mostly","score":2},{"value":"unsure","label":"Unsure","score":1},{"value":"not_right_now","label":"Not Right Now","score":0}]},
    {"key":"u8","heading":"Pause and Reset","section":"suitability","text":"If an activity begins to feel like too much for me at that moment, I am willing to pause, reset and return later rather than pushing myself to continue.","type":"choice","required":true,"reverse":false,"category":"suitability","showIf":null,"practiceId":null,"stopIf":null,"options":[{"value":"yes","label":"Yes","score":3},{"value":"mostly","label":"Mostly","score":2},{"value":"unsure","label":"Unsure","score":1},{"value":"not_right_now","label":"Not Right Now","score":0}]},
    {"key":"u9","heading":"Personal Awareness","section":"suitability","text":"I am willing to notice how I am responding to the program and make choices about my participation based on what feels appropriate for me.","type":"choice","required":true,"reverse":false,"category":"suitability","showIf":null,"practiceId":null,"stopIf":null,"options":[{"value":"yes","label":"Yes","score":3},{"value":"mostly","label":"Mostly","score":2},{"value":"unsure","label":"Unsure","score":1},{"value":"not_right_now","label":"Not Right Now","score":0}]},
    {"key":"u10","heading":"Different Experiences","section":"suitability","text":"I understand that people may experience the QHRT program differently and that individual experiences and outcomes will vary.","type":"choice","required":true,"reverse":false,"category":"suitability","showIf":null,"practiceId":null,"stopIf":null,"options":[{"value":"yes","label":"Yes","score":3},{"value":"mostly","label":"Mostly","score":2},{"value":"unsure","label":"Unsure","score":1},{"value":"not_right_now","label":"Not Right Now","score":0}]},
    {"key":"u11","heading":"Educational Wellness Purpose","section":"suitability","text":"I understand that QHRT is an educational and instructional wellness program designed to support personal well-being and quality of life.","type":"choice","required":true,"reverse":false,"category":"suitability","showIf":null,"practiceId":null,"stopIf":null,"options":[{"value":"yes","label":"Yes","score":3},{"value":"mostly","label":"Mostly","score":2},{"value":"unsure","label":"Unsure","score":1},{"value":"not_right_now","label":"Not Right Now","score":0}]},
    {"key":"u12","heading":"Independent Decision-Making","section":"suitability","text":"I understand that I remain responsible for deciding whether, when and how I participate in the program.","type":"choice","required":true,"reverse":false,"category":"suitability","showIf":null,"practiceId":null,"stopIf":null,"options":[{"value":"yes","label":"Yes","score":3},{"value":"mostly","label":"Mostly","score":2},{"value":"unsure","label":"Unsure","score":1},{"value":"not_right_now","label":"Not Right Now","score":0}]},
    {"key":"u13","heading":"Personal Resources","section":"suitability","text":"I have people, activities, routines or other personal resources I can turn to when I want additional encouragement or assistance.","type":"choice","required":true,"reverse":false,"category":"suitability","showIf":null,"practiceId":null,"stopIf":null,"options":[{"value":"yes","label":"Yes","score":3},{"value":"mostly","label":"Mostly","score":2},{"value":"unsure","label":"Unsure","score":1},{"value":"not_right_now","label":"Not Right Now","score":0}]},
    {"key":"u14","heading":"Privacy and Environment","section":"suitability","text":"I have access to a reasonably private and comfortable environment where I can participate without unnecessary interruption.","type":"choice","required":true,"reverse":false,"category":"suitability","showIf":null,"practiceId":null,"stopIf":null,"options":[{"value":"yes","label":"Yes","score":3},{"value":"mostly","label":"Mostly","score":2},{"value":"unsure","label":"Unsure","score":1},{"value":"not_right_now","label":"Not Right Now","score":0}]},
    {"key":"u15","heading":"Time and Attention","section":"suitability","text":"I can give myself enough time and attention to complete activities without feeling rushed.","type":"choice","required":true,"reverse":false,"category":"suitability","showIf":null,"practiceId":null,"stopIf":null,"options":[{"value":"yes","label":"Yes","score":3},{"value":"mostly","label":"Mostly","score":2},{"value":"unsure","label":"Unsure","score":1},{"value":"not_right_now","label":"Not Right Now","score":0}]},
    {"key":"u16","heading":"Voluntary Participation","section":"suitability","text":"I am choosing to participate in QHRT voluntarily and because the program feels personally relevant to me.","type":"choice","required":true,"reverse":false,"category":"suitability","showIf":null,"practiceId":null,"stopIf":null,"options":[{"value":"yes","label":"Yes","score":3},{"value":"mostly","label":"Mostly","score":2},{"value":"unsure","label":"Unsure","score":1},{"value":"not_right_now","label":"Not Right Now","score":0}]}
  ]$json$,
  $out$[
    {"key":"self_directed","label":"Self-Directed QHRT May Be Suitable for You","summary":"Your responses indicate that you currently have the readiness, comfort and independence needed to begin the self-directed QHRT Wellness Program.\n\nYou remain free to:\n- move at your own pace\n- pause when needed\n- use Preparation & Readiness activities\n- take a break\n- return later\n- access personal resources at any time.","match":"score_range","min":2.2,"max":null,"category":null,"workbookIds":[],"allowSignup":true,"allowSessions":true,"excludeIf":{"questionKey":"s5","values":["yes","unsure"]}},
    {"key":"additional_time","label":"Additional Time or Personal Support May Be Helpful","summary":"Your responses suggest that fully independent participation may not feel like the best starting point for you right now.\n\nThis does not mean that QHRT is unsuitable for you.\n\nYou may simply benefit from:\n- additional preparation\n- more time\n- greater personal support\n- increasing your readiness for the program format\n- creating a more comfortable environment\n- returning when independent participation feels easier.","match":"score_range","min":null,"max":1.49,"category":null,"workbookIds":[],"allowSignup":true,"allowSessions":false,"excludeIf":null},
    {"key":"preparation","label":"Your Best Starting Point Is Preparation & Readiness","summary":"Your responses suggest that spending some time building greater comfort, steadiness and readiness may help you feel better prepared for the main self-directed QHRT program.\n\nPreparation & Readiness may include activities focused on:\n- creating greater comfort\n- becoming more present\n- breathing and settling\n- developing steadiness\n- slowing down\n- increasing your readiness for the program format\n- recognizing when to pause\n- learning how to reset\n- identifying personal resources\n- creating predictable routines\n- strengthening self-trust\n- returning to a comfortable baseline.\n\nAfter completing Preparation & Readiness, you can repeat the Program Readiness & Suitability Check.","match":"fallback","min":null,"max":null,"category":null,"workbookIds":[],"allowSignup":true,"allowSessions":true,"excludeIf":null},
    {"key":"practical","label":"A Few Practical Adjustments May Help","summary":"Your responses suggest that creating more suitable time, privacy or surroundings may help you get more from your QHRT experience.\n\nBefore beginning, consider arranging:\n- enough uninterrupted time\n- a comfortable setting\n- greater privacy\n- fewer distractions\n- a time when you do not feel rushed.","match":"score_range","min":101,"max":101,"category":null,"workbookIds":[],"allowSignup":true,"allowSessions":false,"excludeIf":null},
    {"key":"immediate","label":"Please Seek Immediate Outside Assistance","summary":"Self-directed QHRT is not designed for emergency or crisis situations.\n\nPlease seek immediate assistance before continuing with the QHRT Wellness Program.\n\nFor users in the United States:\n- Call 911 if you or someone else is in immediate danger or requires emergency assistance.\n- Call or text 988 for immediate crisis support through the 988 Suicide & Crisis Lifeline.\n\nResponses submitted through this website are not monitored in real time.","match":"stop","min":null,"max":null,"category":null,"workbookIds":[],"allowSignup":false,"allowSessions":false,"excludeIf":null}
  ]$out$
)
ON CONFLICT (slug) DO NOTHING;
